        Arrays.sort(arr2);

        // Step 2: Initialize two pointers.
        int i = 0; // Pointer for arr1
        int j = 0; // Pointer for arr2

        System.out.print("Common elements are: ");

        // Step 3: Loop until one pointer goes out of bounds.
        while (i < arr1.length && j < arr2.length) {
            // Logic to skip duplicates in arr1 to print each common number only once.
            if (i > 0 && arr1[i] == arr1[i - 1]) {
                i++;
                continue;
            }

            // Step 4: Compare elements.
            if (arr1[i] < arr2[j]) {
                // If element in arr1 is smaller, advance its pointer.
                i++;
            } else if (arr2[j] < arr1[i]) {
                // If element in arr2 is smaller, advance its pointer.
                j++;
            } else {
                // Found a common element!
                System.out.print(arr1[i] + " ");
                // Advance both pointers.
                i++;
                j++;
            }
        }
        System.out.println(); // Newline for clean output.
    }

    // --- Example Usage ---
    public static void main(String[] args) {
        // Example 1: Basic case with unique elements
        int[] array1 = {1, 5, 10, 20, 40, 80};
        int[] array2 = {6, 7, 20, 80, 100};
        findCommonElements(array1.clone(), array2.clone()); // Pass copies
        // Expected Output: Common elements are: 20 80

        System.out.println("--------------------");

        // Example 2: With duplicate elements in both arrays
        int[] array3 = {4, 9, 5, 9, 4};
        int[] array4 = {9, 4, 9, 8, 4};
        findCommonElements(array3.clone(), array4.clone());
        // Expected Output: Common elements are: 4 9

        System.out.println("--------------------");

        // Example 3: No common elements
        int[] array5 = {10, 20, 30};
        int[] array6 = {100, 200, 300};
        findCommonElements(array5.clone(), array6.clone());
        // Expected Output: Common elements are:
    }
}
